content.css:
#top-nav-bar {
    display: flex;
    position: absolute;
    top: 0;
    height: 30px;
    padding: 0px 10px;
    right: 0;
}

#top-nav-bar .nav-items {
    display: flex;
    height: 100%;
    flex-direction: row-reverse;
    align-items: center;
    text-align: center;
    font-size: 16px;
    color: #333;
}

.nav-items.right {
    justify-content: end;
    text-align: right;
}

.nav-items.left {
    justify-content: start;
    text-align: left;
}

.nav-items.right>div {
    width: 30px;
    height: 30px;
}

.vbi-info-icon {
    order: 2;
    width: 28px;
    height: 22px !important;
    margin-left: 2px;
    margin-top: -2px;
}

.vbi-display-data-icon {
    order: 3;
}

.nav-items.right .icon {
    font-size: 24px
}

.vbi-display-data-icon .icon:hover {
    color: #0078d4;
}

.vbi-display-data-icon img {
    width: 28px;
    height: 26px;
    margin-top: 2px;
    margin-right: 2px;
}

.vbi-license-alert-icon {
    order: 1;
    width: 21px !important;
    height: 21px !important;
    margin-top: 2px;
    margin-right: 2px;
}

#vbi-annotation-icon {
    order: 5;
    height: auto;
    width: auto;
}
div#vbi-annotation-icon span{
    font-size: 18px;
    line-height: 32px;
    width: 30px;
    height: 30px;
    color: #333333
}
div#vbi-annotation-icon span.active{
    color: #0078D4;
}

.isEditMode #vbi-edit-icon {
    top: 75px !important;
}

.isEditMode #top-nav-bar {
    top: 40px;
}

/*Settings Icon is Only IBCS Components*/
#pbi-icon-container .settings_icon {
    order: 4;
    padding-left: 14px;
}

.editor-icon {
    order: 7;
    width: 27px !important;
    height: 27px !important;
    border-radius: 50%;
    background-color: #f2c811;
    opacity: 0.8;
    text-align: center;
    line-height: 28px;
    margin-right: 8px;
}
.editor-icon .icon{
    font-size: 12px !important;
    color: #000;
}

.editor-icon:hover {
    -webkit-box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    -moz-box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    box-shadow: -5px 4px 20px 2px rgba(20, 20, 20, 0.2);
    opacity: 1;
}

.editor-icon img {
    border-style: none;
    width: 13px;
    position: relative;
    top: 1px;
    left: 1px;
}
/**** Customize Fonts ****/
@font-face {
  font-family: "Helvetica, sans-serif";
  src: url(data:application/vnd.ms-fontobject;charset=utf-8;base64,);
  src: url(data:application/vnd.ms-fontobject;charset=utf-8;base64,?#iefix) format("eot"), url(data:font/woff2;charset=utf-8;base64,) format("woff2"), url(data:font/woff;charset=utf-8;base64,) format("woff"), url(data:font/ttf;charset=utf-8;base64,) format("truetype");
}
@font-face {
  font-family: "Eurostile, sans-serif";
  src: url(data:font/woff;charset=utf-8;base64,) format("eot"), url(data:font/woff2;charset=utf-8;base64,) format("woff2") format("truetype");
}
@font-face {
  font-family: "FabricMDL2Icons";
  src: url(data:application/vnd.ms-fontobject;charset=utf-8;base64,);
  src: url(data:application/vnd.ms-fontobject;charset=utf-8;base64,?#iefix) format("embedded-opentype"), url(data:font/woff2;charset=utf-8;base64,) format("woff2"), url(data:font/woff;charset=utf-8;base64,) format("woff"), url(data:font/ttf;charset=utf-8;base64,) format("truetype"), url(data:image/svg+xml;charset=utf-8;base64,#font) format("svg");
  font-weight: normal;
  font-style: normal;
}
@media screen and (-webkit-min-device-pixel-ratio: 0) {
  @font-face {
    font-family: "FabricMDL2Icons";
    src: url(data:image/svg+xml;charset=utf-8;base64,#fabric-icons) format("svg");
  }
}
.info-container {
  height: 100%;
}
.info-message {
  vertical-align: middle;
  position: relative;
  top: 50%;
  transform: translateY(-50%);
  text-align: center;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 14px;
  padding: 10px;
}
.loader {
  border: 5px solid #d5d6d8;
  border-radius: 50%;
  border-top: 5px solid #555;
  width: 20px;
  height: 20px;
  display: inline-block;
  -webkit-animation: spin 1s linear infinite;
  animation: spin 1s linear infinite;
}
/* Safari */
@-webkit-keyframes spin {
  0% {
    -webkit-transform: rotate(0deg);
  }
  100% {
    -webkit-transform: rotate(360deg);
  }
}
@keyframes spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
.error-indicator {
  width: 35px;
  height: 35px;
  display: inline-block;
}
.vbi-logo {
  width: 35vh;
  height: 13vh;
  max-width: 93px;
  max-height: 30px;
}
.vbi-logo-gray {
  background-image: url('data:image/png;base64,');
}
.vbi-logo-color {
  background-image: url('data:image/png;base64,');
}
.background-image {
  background-repeat: no-repeat;
  background-size: contain;
}
.close-icon .edit-icon-img {
  display: none !important;
}
.edit-icon .close-icon-img {
  display: none !important;
}
.modal-close-button {
  height: 13px;
  width: 12px;
  right: 4px;
  position: absolute;
  top: 2px;
  z-index: 60;
}
.close-icon-2 {
  background-image: url('data:image/png;base64,');
}
.close-icon-2:hover {
  background-image: url('data:image/png;base64,');
}
.vbi-info-icon {
  background-color: rgba(255, 255, 255, 0.75);
  background-image: url("data:image/svg+xml;base64,");
}
.vbi-info-icon.edit-mode {
  background-image: url("data:image/svg+xml;base64,");
}
.resize-chart {
  height: calc(100% - 40px) !important;
}
.vbi-smoke-screen .modal-close-button {
  display: none !important;
}
.vbi-license-alert-icon {
  height: 24px !important;
  width: 24px !important;
  top: -2px;
  position: relative;
  background-image: url("data:image/svg+xml;base64,");
}
.vbi-info-icon:hover {
  background-image: url("data:image/svg+xml;base64,");
  opacity: 0.5;
}
.vbi-info-icon.edit-mode:hover {
  background-image: url("data:image/svg+xml;base64,");
  opacity: 1;
}
@media (max-width: 231px), (max-height: 151px) {
  .vbi-logo {
    width: 40px;
    height: 15px;
  }
  .vbi-logo-gray {
    width: 40px;
    height: 15px;
    background-image: url('data:image/png;base64,');
  }
}
@media screen and (max-height: 245px) {
  .vbi-license-modal {
    height: 150px !important;
  }
}
.vbi-smoke-screen .vbi-logo-color {
  background-image: url('data:image/svg+xml;base64,');
}
.vbi-error-url a {
  text-decoration: underline;
  color: #f2c811;
}
.vbi-smoke-screen .vbi-error-url a {
  color: blue;
}
.right-bottom-ps {
  position: absolute;
  bottom: 4px;
  right: 4px;
  z-index: 10000000;
}
.right-top-ps {
  position: absolute;
  z-index: 10000000;
  top: 30px;
  right: 4px;
}
.vbi-smoke-screen {
  width: 100%;
  bottom: 0;
  position: absolute;
  background: rgba(250, 250, 250, 0.1);
  z-index: 999;
}
.vbi-smoke-screen .error-span {
  font-size: 20px;
}
.resize-chart {
  width: calc(100% - 400px);
  left: 400px;
}
.remove-resize-chart {
  width: 100% !important;
  left: 0% !important;
}
.resize-chart-right {
  width: calc(100% - 400px);
  right: 400px;
}
.remove-resize-chart-right {
  width: 100% !important;
  right: 0% !important;
}
.infiniteBottom {
  top: 1000000px !important;
}
.plot-area {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0%;
}
.editor--show {
  display: block;
}
.vbi-kpi-tile .kpi-label {
  font-size: 15vh;
  font-weight: 100;
  color: #888484;
}
.vbi-kpi-tile .kpi-value {
  font-size: 20vh;
}
.vbi-show-landing-page {
  width: 100%;
  height: 100%;
  min-width: 500px;
  min-height: 400px;
  vertical-align: middle;
  position: relative;
  top: 30%;
  transform: translateY(-30%);
  text-align: center;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 25px;
  padding: 10px;
}
.vbi-landing-message {
  position: relative;
  top: 40%;
  transform: translateY(-50%);
}
.vbi-title-span {
  height: 10%;
  font-weight: bold;
  font-size: 35px;
}
.vbi-info-url {
  padding: 10px;
}
.vbi-info-url a {
  text-decoration: underline;
  color: #010080;
}
.vbi-logo-div {
  background-image: url('data:image/png;base64,');
  background-position: center;
  margin: auto;
  height: 60px;
  width: 180px;
}
.pro-used-msg,
.buy-licence,
.renew-licence,
.licence-expired-msg,
.no-licence-msg,
.thanks-msg,
.invalid-licence-msg {
  display: none;
}
.invalid-licence .invalid-licence-msg,
.invalid-licence .buy-licence {
  display: block !important;
}
.pro-user .thanks-msg {
  display: block !important;
}
.no-licence .no-licence-msg,
.no-licence .buy-licence {
  display: block !important;
}
.no-license-pro-used .pro-used-msg,
.no-license-pro-used .buy-licence {
  display: block !important;
}
.licence-expired .licence-expired-msg,
.licence-expired .renew-licence {
  display: block !important;
}
.vbi-licence-modal {
  background: #fff;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
  align-items: center;
  color: black;
  font-family: 'Segoe UI', wf_segoe-ui_normal, helvetica, arial, sans-serif;
  top: 42px;
  right: 4px;
  position: absolute;
}
.vbi-licence-modal.pro-user {
  max-height: 220px !important;
}
.vbi-licence-modal.licence-expired {
  max-height: 240px !important;
}
.vbi-licence-modal.editor-icon-present {
  z-index: 99;
}
@media only screen and (max-width: 600px) {
  .vbi-licence-body-item,
  .footer-item {
    width: 100% !important;
  }
  .copy-rights {
    text-align: left !important;
    padding-left: 0px !important;
  }
  .warning-message {
    padding-top: 10px;
  }
  .vbi-licence-modal {
    max-height: 425px !important;
  }
  .vbi-licence-modal.pro-user {
    max-height: 290px !important;
  }
  .vbi-licence-modal.licence-expired {
    max-height: 370px !important;
  }
}
.vbi-licence-modal-item {
  width: 100%;
}
.version-info {
  cursor: pointer;
}
.vbi-logo-licence {
  cursor: pointer;
}
.version-info:hover,
.buy-licence a:hover {
  color: #f2c811 !important;
}
.vbi-logo-licence img {
  height: 25px;
}
.vbi-licence-header {
  display: flex;
  padding-bottom: 7px;
  justify-content: space-between;
  border-bottom: 1px solid #efefef;
  align-items: center;
}
.vbi-licence-modal .chart-name {
  padding: 0px 5px;
  font-weight: 600;
  height: 100%;
}
.vbi-licence-modal .vbi-licence-body {
  padding: 5px;
}
.vbi-licence-modal .info-message-licence {
  width: 50%;
  font-size: 12px;
  padding: 0px 10px;
  box-sizing: border-box;
}
.vbi-licence-modal .info-menu {
  width: 50%;
  padding: 0px 10px;
  box-sizing: border-box;
}
.vbi-licence-modal .menu-item {
  text-transform: uppercase;
  font-weight: 500;
  font-size: 13px;
  padding-bottom: 2px;
  color: #616161;
  cursor: pointer;
}
.vbi-licence-modal .footer a:hover,
.vbi-licence-modal .menu-item:hover {
  color: #f2c811;
}
.vbi-licence-modal .footer {
  border-top: 1px solid #efefef;
  font-size: 12px;
  padding-left: 5px;
  padding-top: 5px;
  color: gray;
  display: flex;
  justify-content: space-between;
  padding-bottom: 10px;
}
.vbi-licence-modal .copy-rights {
  text-align: right;
  width: 30%;
  padding: 0px 5px;
}
.vbi-licence-modal .feedback-link {
  width: 70%;
}
.free-trial-btn {
  margin-top: 5px;
  padding: 8px 8px;
  text-transform: uppercase;
