.form-radio {
  font-size: 0.6rem;
  display: block;
  line-height: 1.2rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-radio input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-radio input:focus + .form-icon {
  border-color: #a6a6a6;
}
.form-radio input:checked + .form-icon {
  background: #f4f4f4;
  border-color: #0078d4;
  box-shadow: none;
}
.form-radio .form-icon {
  border: 0.05rem solid #adadad;
  cursor: pointer;
  display: inline-block;
  position: absolute;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
}
