/** Styles for showing hierarchical columns */
.gridatron .grid-td.hier .grid-cell .icon.hier {
  height: 12px;
  width: 12px;
  background-size: 12px 12px;
  content: "";
  position: absolute;
  margin-left: -24px;
  top: 50%;
  margin-top: -6px;
  z-index: 1;
  background-size: 100%;
  border: 1px #DDD solid;
  display: flex;
  align-items: center;
  justify-content: center;
